column1:
Welcome to Rakudo™ v2026.08."2024-06" ~~ / (\d+) '-' (\d+) { make $0 * 12 + $1 } /;
say $/.made;
"x" ~~ / x { make "a" } { make "b" } /;
say $/.made;
"x" ~~ / x /;
make 7;
say $/.made;
"x" ~~ / y /;
try make 3;
say $!.^name, " ", $!.got.raku;

Welcome to Rakudo™ v2026.08."2026-09" ~~ /(\d+) '-' $<month>=(\d+)/;
say "year $0, month $<month>, all $/";
say "line $?LINE";
say "$*RAKU";
my $h = { a => 1 };
my $l = [1, 2];
say "$h | $l";

Welcome to Rakudo™ v2026.08."a1b2" ~~ / (a) $<n>=(\d) (b) $<m>=(\d) /;
say $/.caps.map({ .key ~ "=" ~ .value });
say $/.keys.sort;
"a-b" ~~ / (\w) '-' (\w) /;
say $/.chunks.map({ .key ~ "=" ~ .value });

Welcome to Rakudo™ v2026.08."ab" ~~ / $<x>=(a) $<y>=[b] /;
say $<x>.Str, $<y>.Str, " ", $/.elems, " ", $/.hash.elems;
my regex a { a }
say ("aa" ~~ / <a> <a> /)<a>.^name;
say ("ab" ~~ / $<x>=(a)+ b /)<x>.^name;
say (""   ~~ / <a>* /)<a>.raku;

Welcome to Rakudo™ v2026.08."ab" ~~ / (a) (X)? (b) /;
say $/.elems;
say $1.raku;
say ($/[1]:exists);
say $/.list.raku;

Welcome to Rakudo™ v2026.08."abc" ~~ / (a) { say "so far: ", ~$/, ", \$0 = ", ~$0, ", pos ", $/.pos } bc /;
"ab" ~~ / :my $count = 5; a { say $count } b /;
my regex word { (\w+) { say "inside word: from ", $/.from } }
"say hello" ~~ / 'say ' <word> /;

Welcome to Rakudo™ v2026.08."abc" ~~ / (a) { say "so far: ", ~$/, ", \$0 = ", ~$0, ", pos ", $/.pos } bc /;
"ab" ~~ / a { say $/ === $¢ } b /;
say $¢.raku;
"ab" ~~ / :my $count = 5; a { say $count } b /;
my regex word { (\w+) { say "inside word: from ", $/.from } }
"say hello" ~~ / 'say ' <word> /;

Welcome to Rakudo™ v2026.08."abc" ~~ / ^ /;
say $/.Bool, " ", $/.Str.raku, " ", $/.gist;
my $m = Match.new(:orig("abc"), :from(2), :pos(1));
say $m.Bool, " ", $m.gist;
say Match.new(:orig("abc"), :from(1), :pos(2)).Str;
say Match.new(:orig("abc"), :from(1), :pos(2), :made(9)).made;

Welcome to Rakudo™ v2026.08."abc" ~~ / b /;
say $/.raku;
"abc" ~~ / x /;
say $/.raku;
say $0.raku;
"abc".match(/ c /);
say ~$/;
"abc".match("a");
say ~$/;
"abc".comb(/ b /);
say ~$/;

Welcome to Rakudo™ v2026.08."abc123def" ~~ / \d+ /;
say $/.from, " ", $/.to, " ", $/.chars;
say $/.prematch, " ", $/.postmatch;
say $/ + 1;
say $/.replace-with("X");
say ("abc" ~~ / b /).Int.^name;

Welcome to Rakudo™ v2026.08."prior" ~~ /o/;
say "abc".subst("b", { $/.Str });
say "abc".subst("b", { .Str.uc });
say "abc".subst(/b/, { $/.Str.uc });
say $/.raku;
my $r = "xyz".subst("y", "_");
say $/.raku;

Welcome to Rakudo™ v2026.08."xxabcxx" ~~ / xx <( abc )> xx /;
say $/.to, " ", $/.pos;
say $/.raku;
say $/.raku.EVAL.Str;

Welcome to Rakudo™ v2026.08."xxabcxx" ~~ / xx <( abc )> xx /;
say ~$/, " ", $/.from, " ", $/.to;
say $/.prematch, "|", $/.postmatch;
say "key=value".match(/ \w+ '=' <( \w+ /).Str;
say "price: 42 EUR".subst(/ \d+ <( \s EUR /, "");

Welcome to Rakudo™ v2026.08.#| Adds one.
sub inc($x) { $x + 1 }
sub dec($x) { $x - 1 }  #= Subtracts one.
#|( Doubles,
    across two lines. )
sub double($x) { $x * 2 }
say &inc.WHY;
say &dec.WHY;
say &double.WHY;

Welcome to Rakudo™ v2026.08.#| Meant for nothing in particular.
say "a statement";
sub later { }
say &later.WHY;

Welcome to Rakudo™ v2026.08.$_ = "a1b2c3";
say (m:g/\d/).^name, " ", (m:g/\d/).elems;
say m:2nd/\d/;
say (m:x(2)/\d/)».Str;
say (m:c(3)/\d/).Str;
say (m:p(0)/\d/).raku;
my @all = m:g/\d/;
say @all.elems;
$_ = "a1";
my $m = m/ \d /;
$_ = "b2";
say $m.Str;

Welcome to Rakudo™ v2026.08.$_ = "abc";
say so / b /;
say / x / ?? "yes" !! "no";
if / c / { say "matched ", ~$/ }
my $r = rx:i/ a.b /;
say $r.gist;
my regex num { \d+ }
say &num.raku;
say "pattern: " ~ $r;

Welcome to Rakudo™ v2026.08.class C { has $.a is required; has $.b is required("give a b") }
try C.new(b => 1);
say $!.^name;
say $!.message;
try C.new(a => 1);
say $!.message;
say C.new(a => Int, b => Nil).a.raku;

Welcome to Rakudo™ v2026.08.class C { has Int $.h is default(7) is rw = 9; has $.plain }
my $c = C.new;
say $c.h;
$c.h = Nil;
say $c.h;
try { $c.h = "s" };
say $!.^name;
try { $c.plain = 1 };
say $!.^name;
say C.new(h => Nil).h;

Welcome to Rakudo™ v2026.08.class C { has Int $.n = 5; has int $!raw = 3 }
my $c = C.new;
my ($n, $raw) = C.^attributes;
say $n.get_value($c);
$n.set_value($c, "not an Int");
say $c.n;
say $raw.get_value($c).^name;
try $raw.set_value($c, "s");
say $!.^name;

Welcome to Rakudo™ v2026.08.class C {
    has $!hidden;
    has Int $.count is rw;
    has @.items;
    has $.name is required;
    has $!secret is built;
    has $.fixed is built(False) = 3;
    has $.five = 5;
    has $.sum = 1 + 1;
}
for C.^attributes {
    say .name.fmt('%-9s'), " ", .type.^name.fmt('%-10s'),
        (.has_accessor ?? " accessor" !! ""), (.rw ?? " rw" !! ""),
        (.required ?? " required" !! ""), (.is_built ?? " built" !! ""),
        " build:", .build.^name;
}

Welcome to Rakudo™ v2026.08.class C {
    has $!secret is built;
    has $.shown is built(False) = "default";
    has $!bound is built(:bind);
    method secret { $!secret }
    method bound-kind { $!bound.VAR.^name }
}
my $c = C.new(secret => 1, shown => 2, bound => 3);
say $c.secret;
say $c.shown;
say $c.bound-kind;
say $c.raku;

Welcome to Rakudo™ v2026.08.class C {
    method m($x) { "m($x)" }
    method n(C:D: $x) { }
}
my $m = C.^lookup('m');
say $m.signature;
say C.^lookup('n').signature;
say $m.arity, " ", $m.count;
say $m.signature.params[0].invocant;
say $m.(C, 1);
say $m.cando(\(C, 1)).elems;
say $m.cando(\(1)).elems;

Welcome to Rakudo™ v2026.08.class C {
    method m($x) { "m($x)" }
    multi method n(Int $x) { "n Int" }
    multi method n(Str $x) { "n Str" }
}
C.^lookup('m').wrap(-> $self, $x { "W<" ~ callsame() ~ ">" });
say C.new.m(1);
C.^lookup('n').candidates[0].wrap(-> $self, $x { "C<" ~ callsame() ~ ">" });
say C.new.n(1);
say C.new.n("s");

Welcome to Rakudo™ v2026.08.class CX::Progress does X::Control {
    has $.done;
    method message { "$!done% done" }
}
sub work {
    for 25, 50, 100 { CX::Progress.new(done => $_).throw }
    "finished"
}
{
    CATCH   { default { say "CATCH: never" } }
    CONTROL { when CX::Progress { say .message; .resume } }
    say work();
}

Welcome to Rakudo™ v2026.08.class CX::Progress does X::Control {
    method message { "progress" }
}
try CX::Progress.new.throw;
say $!.^name, ": ", $!.illegal, " / ", $!.enclosing;
try { for 1..3 { say $_; CX::Last.new.throw } }
say $!.^name, ": ", $!.illegal;
CX::Warn.new(message => "hand-made").throw;
say "not reached";

Welcome to Rakudo™ v2026.08.class Counter {
    has $.n = 0;
    method up(Counter:D:) { $!n + 1 }
    method make(Counter:U:) { self.new }
}
say Counter.make.up;
try Counter.up;
say $!.message;

Welcome to Rakudo™ v2026.08.class E is Exception { }
my $e = E.new;
say $e.Str;
say $e.gist;
try $e.message;
say $!.^name, ": ", $!.message;
E.new.throw;

Welcome to Rakudo™ v2026.08.class Greeter {
    method hello($who) { "hello, $who" }
}
say Greeter.hello("you", :loud);
say Greeter.^lookup('hello').signature;
sub hello($who) { "hello, $who" }
hello("you", :loud);

Welcome to Rakudo™ v2026.08.class Name is Str {}
my $n = Name.new(value => "ada lovelace");
say $n.uc.^name;
say $n.words[0].^name;
say ($n ~ "!").^name;
say ($n x 2).^name;
say $n eq "ada lovelace";
say $n eqv "ada lovelace";

Welcome to Rakudo™ v2026.08.class Noisy { has $.name; method sink { say "sunk $!name" } }
(Noisy.new(name => "first"), Noisy.new(name => "second"));
Noisy.new(name => "repeated") xx 2;
Noisy.new(name => "modifier") for 1, 2;

Welcome to Rakudo™ v2026.08.class Noisy { has $.name; method sink { say "sunk $!name" } }
if True { Noisy.new(name => "if") }
for 1 { Noisy.new(name => "for") }
{ Noisy.new(name => "bare block") }
my $v = do { Noisy.new(name => "do") };
my $t = try { Noisy.new(name => "try") };
given Noisy.new(name => "topic") { Noisy.new(name => "given") }
say $v.name, " ", $t.name;

Welcome to Rakudo™ v2026.08.class Noisy { has $.name; method sink { say "sunk $!name" } }
my $n = 0;
(1, 2).map({ $n++; Noisy.new(name => "element $_") });
say $n;

Welcome to Rakudo™ v2026.08.class Noisy { has $.name; method sink { say "sunk $!name" } }
sub make($n)  { Noisy.new(name => $n) }
sub early($n) { return Noisy.new(name => $n) }
sub two       { Noisy.new(name => "not last"); make("kept") }
make("implicit");
early("explicit");
my $kept = two();

Welcome to Rakudo™ v2026.08.class Noisy { has $.name; method sink { say "sunk $!name" } }
sub make($name) { Noisy.new(:$name) }
for 1 { make("block, sub call") }
for 1 -> $x { make("pointy block, sub call") }
for 1 -> $x { Noisy.new(name => "pointy block, method call") }
try { for 1 { make("block inside try") }; Nil }

Welcome to Rakudo™ v2026.08.class Noisy { has $.name; method sink { say "sunk $!name" } }
sub one { 1 }
Noisy.new(name => "condition") ?? one() !! one();
one() ?? Noisy.new(name => "branch") !! one();
Noisy.new(name => "left of ||") || one();
Noisy.new(name => "left of &&") && one();
one() andthen Noisy.new(name => "right of andthen");

Welcome to Rakudo™ v2026.08.class Noisy { has $.name; method sink { say "sunk $!name" } }
sub one { 1 }
Noisy.new(name => "left of ||") || one();
Noisy.new(name => "left of or") or one();
Noisy.new(name => "left of //") // one();
Noisy.new(name => "left of orelse") orelse one();

Welcome to Rakudo™ v2026.08.class Noisy {
    has $.name;
    method sink { say "sunk $!name" }
}
Noisy.new(name => "a");
my $kept = Noisy.new(name => "b");
Noisy.new(name => "c").name;
my @list = Noisy.new(name => "d");
Noisy.new(name => "e");

Welcome to Rakudo™ v2026.08.class Point { has $.x }
my $p = Point.new(x => 1);
say $p ~~ $p;
say $p ~~ Point.new(x => 1);
say Point ~~ $p;
say $p ~~ Point;
say 42 ~~ 42.0;
say Int ~~ 42;

Welcome to Rakudo™ v2026.08.class Point {
    has $.x;
    has $!y;
    submethod BUILD(:$!x, :$!y = 0) { }
    method set-y($!y) { }
    method y { $!y }
}
my $p = Point.new(x => 1, y => 2);
say $p.x, " ", $p.y;
$p.set-y(5);
say $p.y;
say Point.^lookup('set-y').signature;

Welcome to Rakudo™ v2026.08.class Shout does Encoding {
    method name { "shout" }
    method alternative-names { ("loud",) }
    method encoder(*%) {
        class :: does Encoding::Encoder {
            method encode-chars(Str $s) { $s.uc.encode("ascii") }
        }.new
    }
    method decoder(*%) { die "no decoder" }
}
say Encoding::Registry.register(Shout).raku;
say "hi".encode("LOUD").raku;
try { Encoding::Registry.register(Shout) };
say $!.^name;
try { Encoding::Registry.register(Encoding::Registry.find("utf8")) };
say $!.message;

Welcome to Rakudo™ v2026.08.class X::Empty is Exception {
    has $.what;
    method message { "$!what is empty" }
}
sub first-of(@list) {
    X::Empty.new(what => "the list").throw unless @list;
    @list[0]
}
try first-of([]);
say $!.^name;
say $!.message;
say $!.what;
first-of([]);

Welcome to Rakudo™ v2026.08.enum Colour <Red Green Blue>;
say Green.keys.sort;
say Green.values.sort;
say Colour.keys.sort;
say Green.elems;
say Green.kv;
say True.keys.sort;
say True.kv.elems;

Welcome to Rakudo™ v2026.08.for "Inf", "1/0", "1+2i", "abc" -> $s {
    try $s.Int;
    say "$s: ", $!.^name;
}
say (try "-1".UInt) // $!.^name;
say "1/0".Rat.raku;
say "1/0".Num;

Welcome to Rakudo™ v2026.08.for "e\x[301]", "x\x[301]", "\r\n",
    "\x[1F468]\x[200D]\x[1F469]\x[200D]\x[1F467]", "\x[1F1FA]\x[1F1F8]" -> $s {
    say "{$s.chars} {$s.codes} {$s.encode.bytes}";
}
say "é".NFD.list;

Welcome to Rakudo™ v2026.08.for "index", "starts-with", "ends-with" -> $method {
    try "abc"."$method"(/b/);
    say "$method: ", $!.^name;
}
try "abc".substr(/b/, 1);
say $!.^name;
say $!.message;

Welcome to Rakudo™ v2026.08.for "x", Inf, NaN, 3i -> $w {
    try { ("a" => $w).Bag };
    say "Bag {$w.raku}: ", $!.^name;
}
for "x", Inf, NaN, 3i -> $w {
    try { ("a" => $w).Mix };
    say "Mix {$w.raku}: ", $!.^name;
}
try { ("a" => Inf).Mix };
say $!.message;

Welcome to Rakudo™ v2026.08.for 1..2 {
    NEXT  say "NEXT $_";
    LEAVE say "LEAVE $_";
    LAST  say "LAST $_";
    say "body $_";
}

Welcome to Rakudo™ v2026.08.for 1..3 {
    CONTROL { default { say "control: ", .^name, " ", .message } }
    next if $_ == 1;
    last if $_ == 2;
}

Welcome to Rakudo™ v2026.08.for 1..3, 7..8 { say .raku }
my $s = 0;
$s += $_ for 1..3, 7..8;
say $s;
say (flat 1..3, 7..8).elems;
my @bound := 1..3;
say @bound.^name;
my @copied = 1..3;
say @copied.^name;

Welcome to Rakudo™ v2026.08.for 1..4 -> $n {
    CATCH { default { say "stop at $n"; last } }
    die "too big" if $n == 3;
    say $n;
}
my $attempts = 0;
for <a b> -> $item {
    CATCH { default { say "retrying $item"; redo } }
    die "flaky" if $item eq "a" && $attempts++ == 0;
    say "done $item";
}

Welcome to Rakudo™ v2026.08.for 1..4 {
    CATCH { default { say "skipped $_" } }
    die "odd" if $_ %% 2;
    say $_;
}

Welcome to Rakudo™ v2026.08.for 1..4 {
    CONTROL { when CX::Last { say "last swallowed" } }
    last if $_ == 2;
    say $_;
}
for 1..4 {
    CONTROL { when CX::Last { say "last passed on"; .rethrow } }
    last if $_ == 2;
    say $_;
}

Welcome to Rakudo™ v2026.08.for <elems Bool Str gist raku cache join sum head list eager sort> -> $method {
    my $s = (1..3).map(* * 2);
    my $result = $s."$method"();
    say "$method: ", (try $s.join(",")) // $!.^name;
}
my $t = (1..3).map(* * 2);
say $t[1];
say $t.join(",");

Welcome to Rakudo™ v2026.08.for <true false> -> $cmd { run $cmd }
say "the failure went unnoticed";
for <true false> -> $cmd { sink run $cmd }
say "not reached";

Welcome to Rakudo™ v2026.08.for Blob.new(255), Blob.new(195), Blob.new(0xC0, 0x80), Blob.new(0xED, 0xA0, 0x80) -> $b {
    try { $b.decode };
    say $!.^name, ": ", $!.message;
}
try { Blob.new(200).decode("ascii") };
say $!.message;

Welcome to Rakudo™ v2026.08.for Inf, NaN, 2**31 -> $n {
    try { my $s = "ab" x $n };
    say $!.message;
}

Welcome to Rakudo™ v2026.08.grammar A { token TOP { <x> <y> }; token x { a }; token y { b } }
grammar B is A { token x { c } }
say B.parse("cb").Str;
say B.parse("ab").raku;
say B.parse("cb") ~~ A;
grammar J is A { token x { c | <.A::x> } }
say J.parse("ab").Str, " ", J.parse("cb").Str;

Welcome to Rakudo™ v2026.08.grammar Digits { token TOP { \d+ } }
my $m = Digits.parse(123);
say $m.orig.^name, " ", $m.target.^name;
say $m.raku;
say Digits.parse(12.5).raku;
say Digits.parse(1e3).Str;
say Digits.parse(12) + 1;
for Any, Nil, Int -> \target {
    quietly try Digits.parse(target);
    say $!.^name;
}

Welcome to Rakudo™ v2026.08.grammar Empty {}
try Empty.parse("x");
say $!.message;
try Grammar.parse("x");
say $!.message;
grammar G { token TOP { x } }
say G.new.raku;

Welcome to Rakudo™ v2026.08.grammar G { token TOP { a { make "body" } } }
say G.parse("a").made;
say G.parse("a", :actions(class { method TOP($/) { make "action" } })).made;
say G.parse("a", :actions(class { method TOP($/) { } })).made;

Welcome to Rakudo™ v2026.08.grammar G { token TOP { a } }
say G.parse("a", :actions(class Acts { })).actions.^name;
say G.parse("a").actions.^name;
say G.parse("a").actions;

Welcome to Rakudo™ v2026.08.grammar G { token TOP { a+ } }
my $m = G.parse("aaa");
say $m.^name, " ", $m ~~ Match;
say G.^mro.map(*.^name);
say G.parse("aab").raku;
say $/.raku;

Welcome to Rakudo™ v2026.08.grammar G { token TOP { a+ } }
say G.subparse("aab").Str;
my $failed = G.subparse("bbb");
say $failed.Bool, " ", $failed.gist;
say $failed.to, " ", $failed.pos;
say $failed.raku;
say $/.^name, " ", $/.Bool;

Welcome to Rakudo™ v2026.08.grammar G { token TOP { a+ }; token b { b } }
say G.^find_method("TOP").^name;
say G.^find_method("TOP").signature.raku;
my $m = G.new(:orig("aaab")).TOP;
say $m.Str, " ", $m.^name, " ", $m.pos;
say G.new(:orig("xb"), :pos(1)).b.Str;
say G.new(:orig("baa")).TOP.Bool;
try G.TOP("aaa");
say $!.^name;

Welcome to Rakudo™ v2026.08.grammar G {
    token TOP { a+ }
    token b { b+ }
    token rep($c) { $c+ }
}
say G.parse("bb", :rule<b>).^name;
say G.parse("ccc", :rule<rep>, :args(\("c"))).Str;
say G.parse("ccc", :rule<rep>, :args(("c",))).Str;
say G.parse("bbaa", :pos(2)).Str;
say G.parse("bbaa", :pos(2)).prematch;
try G.parse("x", :rule<nope>);
say $!.^name;
try G.parse("ccc", :rule<rep>);
say $!.^name;
try G.parse("ccc", :rule<rep>, :args("c"));
say $!.^name;

Welcome to Rakudo™ v2026.08.grammar J {
    token TOP { <op> }
    proto token op {*}
    token op:sym<x> { x <?{ False }> }
    token op:sym<y> { x }
    token op:sym<+> { <sym> }
}
say J.parse("x")<op>.Str;
say J.parse("+", :rule("op:sym<+>")).Str;
say J.^methods.map(*.name).grep(*.starts-with("op")).sort;

Welcome to Rakudo™ v2026.08.grammar Limited {
    has $.limit = 0;
    token TOP { \d+ <?{ $/.Int <= self.limit }> }
}
say Limited.parse("42", :limit(50)).Str;
say Limited.parse("42", :limit(10)).raku;
say Limited.new(:limit(50)).parse("42").raku;
say Limited.parse("42", :limit(50)).limit.raku;

Welcome to Rakudo™ v2026.08.grammar Limited {
    has $.limit = 0;
    token TOP { \d+ <?{ $/.Int <= self.limit }> }
}
say Limited.parse("42", :limit(50)).Str;
say Limited.parse("42", :limit(10)).raku;
say Limited.new(:limit(50)).parse("42").raku;
say Limited.parse("42", :limit(50)).limit.raku;
say Limited.parse("42", :limit(50), :nope(1)).Str;

Welcome to Rakudo™ v2026.08.grammar R { regex TOP { a || aa } }
grammar T { token TOP { a || aa } }
grammar L { token TOP { a | aa } }
say R.parse("aa").Str;
say T.parse("aa").raku;
say L.parse("aa").Str;
say R.subparse("aa").Str;

Welcome to Rakudo™ v2026.08.grammar S { token TOP { <ws> a <ws> b } }
my $m = S.parse(" a b");
say $m<ws>.elems, " ", $m<ws>[0].Str.raku;
grammar Q { token TOP { <.ws> a <.ws> b } }
say Q.parse(" a b").keys;

Welcome to Rakudo™ v2026.08.grammar Sum {
    token TOP { <num> '+' <num> }
    token num { \d+ }
}
class Calc {
    method TOP($/) { make $<num>[0].made + $<num>[1].made }
    method num($/) { make +$/ }
}
say Sum.parse("2+3", :actions(Calc)).made;
say Sum.parse("2+3").made.raku;
say Sum.parse("42", :actions(Calc), :rule<num>).made;
Sum.parse("4+5", :actions(Calc));
say $/.made;

