print run("sh", "-c", 'echo "[$GREETING] [$HOME]"', :env{ GREETING => "hi" }, :out).out.slurp(:close);
{
    temp %*ENV<GREETING> = "from temp";
    print run("sh", "-c", 'echo "[$GREETING]"', :out).out.slurp(:close);
}
rmdir "sub";

